mapper.select:
SELECT
,t.taolun_title as taolunTitle FROM taolun_huifu a LEFT JOIN taolun t ON a.taolun_id = t.id LEFT JOIN xuesheng xuesheng ON a.huifuren_table = 'xuesheng' AND a.huifuren_id = xuesheng.id LEFT JOIN laoshi laoshi ON a.huifuren_table = 'laoshi' AND a.huifuren_id = laoshi.id LEFT JOIN qiye qiye ON a.huifuren_table = 'qiye' AND a.huifuren_id = qiye.id LEFT JOIN users users ON a.huifuren_table = 'users' AND a.huifuren_id = users.id
and a.id in
#{item}
and a.taolun_id = #{params.taolunId}
and a.huifuren_id = #{params.huifurenId}
and a.huifuren_role = #{params.huifurenRole}
and a.huifuren_table = #{params.huifurenTable}
and ( a.huifuren_name like CONCAT('%',#{params.huifurenName},'%') or xuesheng.xuesheng_name like CONCAT('%',#{params.huifurenName},'%') or laoshi.laoshi_name like CONCAT('%',#{params.huifurenName},'%') or qiye.qiye_name like CONCAT('%',#{params.huifurenName},'%') or users.username like CONCAT('%',#{params.huifurenName},'%') )
and t.taolun_title like CONCAT('%',#{params.taolunTitle},'%')
and a.huifu_content like CONCAT('%',#{params.huifuContent},'%')
order by a.${params.orderBy} desc
